import sys

def main():
    line = sys.stdin.read().strip()
    if not line:
        return
    n1, n2, k1, k2 = map(int, line.split())

    moves1 = (n1 - 1) // k1
    moves2 = (n2 - 1) // k2

    if moves1 > moves2:
        print("First")
    else:
        print("Second")

if __name__ == "__main__":
    main()
